prompt --application/shared_components/user_interface/lovs/shift_lov_pack
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(119853987215005690)
,p_lov_name=>'SHIFT_LOV_PACK'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- LOV for current user',
'SELECT ''Morning'' AS shift',
'FROM DUAL',
'WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'UNION ALL',
'SELECT ''Night '' AS shift',
'FROM DUAL',
'WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'UNION ALL',
'/*SELECT ''O Shift'' AS shift',
'FROM DUAL',
'WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'UNION ALL*/',
'-- For all other users, show only the current shift based on time',
'SELECT CASE ',
'           WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 0800 AND 1959 THEN ''Morning''',
'           --WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 2000 AND 0759 THEN ''Evening''',
'           ELSE ''Night''',
'       END AS shift',
'FROM DUAL',
'WHERE :APP_USER NOT IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'',
'',
'--27/3/26',
'-- -- LOV for current user',
'-- SELECT ''Morning'' AS shift',
'-- FROM DUAL',
'-- WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'-- UNION ALL',
'-- SELECT ''Evening'' AS shift',
'-- FROM DUAL',
'-- WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'-- UNION ALL',
'-- SELECT ''O Shift'' AS shift',
'-- FROM DUAL',
'-- WHERE :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'-- UNION ALL',
'-- -- For all other users, show only the current shift based on time',
'-- SELECT CASE ',
'--            WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 800 AND 1629 THEN ''Morning''',
'--            WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 1630 AND 2359 THEN ''Evening''',
'--            ELSE ''O Shift''',
'--        END AS shift',
'-- FROM DUAL',
'-- WHERE :APP_USER NOT IN (''AMIR'', ''ZAIN'', ''SHAHID'',''M.MOHSIN'')',
'',
'',
'-- SELECT :APP_USER AS app_user,',
'--        CASE ',
'--            WHEN :APP_USER IN (''AMIR'', ''ZAIN'', ''SHAHID'') THEN ''Morning, Evening, O Shift''',
'--            WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 800 AND 1629 THEN ''Morning''',
'--            WHEN TO_NUMBER(TO_CHAR(SYSDATE, ''HH24MI'')) BETWEEN 1630 AND 2359 THEN ''Evening''',
'--            ELSE ''O Shift''',
'--        END AS shift',
'-- FROM DUAL;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'SHIFT'
,p_display_column_name=>'SHIFT'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'SHIFT'
,p_default_sort_direction=>'ASC'
);
end;
