'// Apply animated border to all popup LOVs',
'document.querySelectorAll(''.apex-item-group--popup-lov'').forEach(el => {',
'  el.classList.add(''animated-border'');',
'});',
'',
'',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#my_report table tr td:first-child:contains(''TOTAL'') {',
'    background-color: #ffeb3b;  /* yellow background */',
'    font-weight: bold;',
'    color: #000;',
'}',
'',
unistr('/* \D83C\DFA8 Simple 3-color animated border for popup LOV */'),
'.apex-item-group--popup-lov.animated-border',
' {',
'  position: relative;',
'  z-index: 1;',
'}',
'',
'/* Create animated gradient border using ::after */',
'.apex-item-group--popup-lov.animated-border::after {',
'  content: "";',
'  position: absolute;',
'  top: -2px;',
'  left: -2px;',
'  right: -2px;',
'  bottom: -2px;',
'  border-radius: 8px;',
'  background: linear-gradient(90deg, #e10000, #059aae, #03bb56);',
'  background-size: 300% 300%;',
'  animation: borderFlow 3s linear infinite;',
'  z-index: -1;',
'}',
'',
'/* Optional: subtle glow */',
'.apex-item-group--popup-lov.animated-border::before {',
'  content: "";',
'  position: absolute;',
'  top: -3px;',
'  left: -3px;',
'  right: -3px;',
'  bottom: -3px;',
'  border-radius: 8px;',
'  background: inherit;',
'  filter: blur(6px);',
'  opacity: 0.6;',
'  z-index: -2;',
'  animation: borderFlow 3s linear infinite;',
'}',
'',
'/* Animation for smooth color flow */',
'@keyframes borderFlow {',
'  0%   { background-position: 0% 50%; }',
'  50%  { background-position: 100% 50%; }',
'  100% { background-position: 0% 50%; }',
'}',
'',
'',
'',
