wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(172880261170543512)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Retreive'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    CURSOR c_carton_data IS',
'        SELECT H.CARTON_ID,',
'               H.CARTON_NO,',
'               H.ACTUAL_WT,',
'',
'               CASE',
'                   WHEN COUNT(DISTINCT D.CUSTOMER_COLOR) > 1',
'                   THEN ''MIX_COLOR''',
'                   ELSE MAX(D.CUSTOMER_COLOR)',
'               END AS CUSTOMER_COLOR,',
'',
'               CASE',
'                   WHEN COUNT(DISTINCT D.GARMENTS_SIZE) > 1',
'                   THEN ''MIX_SIZE''',
'                   ELSE MAX(D.GARMENTS_SIZE)',
'               END AS GARMENTS_SIZE,',
'',
'               CASE',
'                   WHEN COUNT(DISTINCT D.INSEAM) > 1',
'                   THEN ''MIX_INSEAM''',
'                   ELSE MAX(D.INSEAM)',
'               END AS INSEAM,',
'',
'               COUNT(D.ID) PACKED_PCS',
'',
'        FROM apps.M6_CARTON_PACK_BC_H@PRODDB H,',
'             apps.M6_CARTON_PACK_BC_D@PRODDB D',
'        WHERE H.CARTON_ID = D.CARTON_ID',
'          AND H.CUSTOMER_PO = :P3_CUSTOMER_PO',
'          AND H.COUNTRY     = :P3_DESTINATION',
'        AND NOT EXISTS (',
'                        SELECT 1',
'                        FROM M6_QA_PACK_INLINE_ENDLINE_L L ',
'                        WHERE  l.BAR_CARTON_ID =h.CARTON_ID',
'                        )',
'        GROUP BY H.CARTON_ID,',
'                 H.CARTON_NO,',
'                 H.ACTUAL_WT;',
'',
'BEGIN',
'',
'    FOR rec IN c_carton_data LOOP',
'',
'        BEGIN',
'',
'            INSERT INTO M6_QA_PACK_INLINE_ENDLINE_L',
'            (',
'                DOCUMENT_NO,',
'                PACKING_TYPE,',
'                COLOR,',
'                PACK_SIZE,',
'                REQ_QTY,',
'                PACK_QTY,',
'                WEIGHT,',
'                REMARKS,',
'                PORTION,',
'                REPACK,',
'                ENTRY_TYPE,',
'                CUSTOMER_CARTON_NO,',
'                BAR_CARTON_ID',
'            )',
'            VALUES',
'            (',
'                :P3_DOCUMENT_NO,',
'                ''SOLID'',',
'                rec.CUSTOMER_COLOR,',
'                rec.GARMENTS_SIZE,',
'                rec.PACKED_PCS,',
'                rec.PACKED_PCS,',
'                rec.ACTUAL_WT,',
'                rec.INSEAM,',
'                NULL,',
'                ''N'',',
'                ''AUTO'',',
'                rec.CARTON_NO,',
'                rec.CARTON_ID',
'            );',
'',
'        EXCEPTION',
'            WHEN DUP_VAL_ON_INDEX THEN',
'                NULL;',
'        END;',
'',
'    END LOOP;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(172879928937543509)
,p_process_when=>'P3_DOCUMENT_NO'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>172880261170543512
);
