wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(172879328136543503)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_REQ_QTY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    l_req_qty      NUMBER := 0;',
'    l_packing_qty  NUMBER := 0;',
'',
'BEGIN',
'',
'    -----------------------------------',
'    -- QUERY 1 : REQ QTY',
'    -----------------------------------',
'',
'    SELECT NVL(SUM(d.qty),0)',
'    INTO l_req_qty',
'    FROM APPS.M6_PACKING_LIST_BARCODE_H@proddb h,',
'         APPS.M6_PACKING_LIST_BARCODE_D@proddb d',
'    WHERE h.document_no = d.document_no',
'    AND h.tracking_no   = apex_application.g_x01',
'    AND h.customer_po   = apex_application.g_x02',
'    AND h.country       = apex_application.g_x03;',
'',
'    -----------------------------------',
'    -- QUERY 2 : PACKING QTY',
'    -----------------------------------',
'',
'    SELECT NVL(COUNT(d.id),0)',
'    INTO l_packing_qty',
'    FROM apps.M6_CARTON_PACK_BC_H@proddb h,',
'         apps.M6_CARTON_PACK_BC_D@proddb d',
'    WHERE h.carton_id   = d.carton_id',
'    AND h.customer_po   = apex_application.g_x02',
'    AND h.country       = apex_application.g_x03;',
'',
'    -----------------------------------',
'    -- JSON RESPONSE',
'    -----------------------------------',
'',
'    apex_json.open_object;',
'',
'    apex_json.write(''req_qty'', l_req_qty);',
'',
'    apex_json.write(''packing_qty'', l_packing_qty);',
'',
'    apex_json.close_object;',
'',
'END;',
'',
'',
'',
'-- DECLARE',
'',
'--     l_req_qty NUMBER;',
'',
'-- BEGIN',
'',
'--     SELECT NVL(SUM(d.qty),0)',
'--     INTO l_req_qty',
'--     FROM APPS.M6_PACKING_LIST_BARCODE_H@proddb h,',
'--          APPS.M6_PACKING_LIST_BARCODE_D@proddb d',
'--     WHERE h.document_no = d.document_no',
'--     AND h.tracking_no   = apex_application.g_x01',
'--     AND h.customer_po   = apex_application.g_x02',
'--     AND h.country       = apex_application.g_x03;',
'',
'--     apex_json.open_object;',
'--     apex_json.write(''req_qty'', l_req_qty);',
'--     apex_json.close_object;',
'',
'-- END;',
'',
'',
'-- DECLARE',
'',
'--     l_req_qty NUMBER;',
'',
'-- BEGIN',
'',
'--         SELECT sum(d.qty) ',
'--         INTO l_req_qty',
'--         FROM M6_PACKING_LIST_BARCODE_H@proddb H,M6_PACKING_LIST_BARCODE_d@proddb d',
'--         WHERE 1=1',
'--         and h.document_no=d.document_no',
'--         AND H.CUSTOMER_PO = apex_application.g_x01;  --''MTELSC4630492''',
'--         AND H.TRACKING_NO = apex_application.g_x02;  --''TSN-2507-0009R02''',
'--         AND H.COUNTRY=apex_application.g_x03;   --''DENMARK'';',
'',
'',
'--     -- SELECT POCH.EXCESS_ORDER_QTY',
'--     -- INTO l_req_qty',
'--     -- FROM PWC_ONT_WVN_PRECOSTING_H@proddb POCH',
'--     -- WHERE tracking_no = apex_application.g_x01;',
'',
'',
'--     apex_json.open_object;',
'--     apex_json.write(''req_qty'', l_req_qty);',
'--     apex_json.close_object;',
'',
'-- EXCEPTION',
'--     WHEN NO_DATA_FOUND THEN',
'--         apex_json.open_object;',
'--         apex_json.write(''req_qty'', 0);',
'--         apex_json.close_object;',
'',
'-- END;',
'',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>172879328136543503
);
end;
