wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(99644162313134916)
,p_chart_id=>wwv_flow_imp.id(99642386325134909)
,p_seq=>10
,p_name=>'Line Wise Packing Quantity'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select h.line_no, SUM(L.PACK_QTY) AS PACK_QTY',
'from M6_QA_PACK_INLINE_ENDLINE_H h',
'join M6_QA_PACK_INLINE_ENDLINE_L L ',
'   on H.DOCUMENT_NO = L.DOCUMENT_NO',
'where h.document_date BETWEEN NVL(:P5_FROM_DATE, h.document_date) AND NVL(:P5_TO_DATE, h.document_date)',
'  and h.customer_name = NVL(:P5_CUSTOMER_NAME, h.customer_name)',
'  and h.SHIFT = NVL(:P5_SHIFT, h.SHIFT)',
'  and (:P5_COLOR IS NULL OR L.COLOR = :P5_COLOR)',
'  and (:P5_MASTER_PO IS NULL OR h.TRACKING_NO = :P5_MASTER_PO)',
'  and (:P5_LINEWISE IS NULL OR h.line_no = :P5_LINEWISE)',
'group by h.line_no',
'',
'',
'',
'',
'-- select  H.LINE_NO,',
'--  SUM (L.PACK_QTY)AS PACK_QTY',
'-- from M6_QA_PACK_INLINE_ENDLINE_H h ,',
'--  M6_QA_PACK_INLINE_ENDLINE_L L',
'--  WHERE H.DOCUMENT_NO = L.DOCUMENT_NO',
'--  AND h.document_date BETWEEN NVL(:P5_FROM_DATE, h.document_date)',
'-- AND NVL(:P5_TO_DATE,   h.document_date)',
'-- and h.customer_name = NVL(:P5_CUSTOMER_NAME, h.customer_name)',
'-- and (h.SHIFT IS NULL OR SHIFT = :P5_SHIFT)',
'-- and h.TRACKING_NO=nvl(:P5_MASTER_PO,TRACKING_NO)',
'-- AND h.line_no       = NVL(:P5_LINEWISE, h.line_no)',
'--  --AND TRUNC(DOCUMENT_DATE) = TRUNC(SYSDATE)',
'--  --AND LINE_NO = :LINE_NO--''LINE # 01''',
'--  GROUP BY H.LINE_NO',
'',
'',
''))
,p_ajax_items_to_submit=>'P5_FROM_DATE,P5_TO_DATE,P5_CUSTOMER_NAME,P5_SHIFT,P5_MASTER_PO,P5_LINEWISE,P5_COLOR'
,p_series_name_column_name=>'LINE_NO'
,p_items_value_column_name=>'PACK_QTY'
,p_items_label_column_name=>'LINE_NO'
,p_assigned_to_y2=>'off'
,p_items_label_rendered=>false
);
